// Por agencia: las etapas del pipeline y las oportunidades más recientes (5 páginas de 100 = 2+ semanas)
const AG = { independencia: '2O4BBoTVOs95TgWbel6e', centro: 'oC2FNTV3Dc5yhLyrGvoy', periodismo: 'Jf5jBydZMO0fdMeo1d4O', matriz: 'UIJiu5Wa9iPVzMpbaZcx', hijar: '4xUuPucjdj14sqVme6sO' };
const out = [];
for (const [agencia, loc] of Object.entries(AG)) {
  out.push({ json: { agencia, method: 'GET', path: `/opportunities/pipelines?locationId=${loc}`, ctx: { tipo: 'pipes' } } });
  for (let page = 1; page <= 5; page++)
    out.push({ json: { agencia, method: 'GET', path: `/opportunities/search?location_id=${loc}&limit=100&page=${page}&order=added_desc`, ctx: { tipo: 'opps', page } } });
}
return out;

// Arma el reporte semanal: leads de los últimos 7 días por agencia, comparado con la semana anterior
const NOMBRES = { independencia: 'Independencia', centro: 'Centro', periodismo: 'Periodismo', matriz: 'Matriz', hijar: 'Hijar' };
const ahora = Date.now(), DIA = 864e5;
const etapas = {}, opps = {};
for (const it of $('GHL por agencia').all()) {
  const { agencia, ctx, res } = it.json;
  if (ctx.tipo === 'pipes') {
    etapas[agencia] = etapas[agencia] || {};
    for (const p of res.pipelines || []) for (const s of p.stages || []) etapas[agencia][s.id] = { nombre: s.name, pos: s.position };
  } else {
    opps[agencia] = (opps[agencia] || []).concat(res.opportunities || []);
  }
}
const grupo = (n) => {
  if (/anticipo|pagado|mañana sale|en destino|de regreso|ganado/i.test(n)) return 'ventas';
  if (/datos completos|cotizaci/i.test(n)) return 'cotizacion';
  if (/[uú]ltima oportunidad|perdido/i.test(n)) return 'perdidos';
  if (/sin ia/i.test(n)) return 'sinIA';
  return 'conversando';
};
const filas = [];
for (const ag of Object.keys(NOMBRES)) {
  const vistos = new Set();
  const lista = (opps[ag] || []).filter(o => !vistos.has(o.id) && vistos.add(o.id) && !/^prueba (ia|diaria)/i.test(o.name || ''));
  const edad = (o) => (ahora - new Date(o.createdAt).getTime()) / DIA;
  const semana = lista.filter(o => edad(o) <= 7);
  const anterior = lista.filter(o => edad(o) > 7 && edad(o) <= 14).length;
  const g = { ventas: 0, cotizacion: 0, perdidos: 0, sinIA: 0, conversando: 0 };
  const porEtapa = {};
  for (const o of semana) {
    const e = (etapas[ag] || {})[o.pipelineStageId] || { nombre: 'Otra', pos: 99 };
    g[grupo(e.nombre)]++;
    porEtapa[e.nombre] = porEtapa[e.nombre] || { n: 0, pos: e.pos };
    porEtapa[e.nombre].n++;
  }
  filas.push({ ag, nombre: NOMBRES[ag], total: semana.length, anterior, ...g,
    etapas: Object.entries(porEtapa).sort((a, b) => a[1].pos - b[1].pos).map(([n, v]) => [n, v.n]) });
}
// Pruebas diarias de la semana
const pruebas = $('Pruebas de la semana').all().map(i => i.json).filter(p => p && p.agencia);
const pr = {};
for (const p of pruebas) {
  pr[p.agencia] = pr[p.agencia] || { ok: 0, total: 0, fallos: [] };
  pr[p.agencia].total++;
  if (p.ok) pr[p.agencia].ok++;
  else pr[p.agencia].fallos.push(`${String(p.fecha).slice(0, 10)}: ${p.paso || ''} ${p.detalle || ''}`.trim());
}
const pct = (a, b) => b ? Math.round(a * 100 / b) + ' %' : '–';
const flecha = (a, b) => !b ? (a ? '🆕' : '') : a > b ? `<span style="color:#1a7f37">↑ ${Math.round((a - b) * 100 / b)} %</span>` : a < b ? `<span style="color:#cf222e">↓ ${Math.round((b - a) * 100 / b)} %</span>` : '=';
const fmt = (d) => new Date(d).toLocaleDateString('es-MX', { day: 'numeric', month: 'short', timeZone: 'America/Mexico_City' });
const td = 'style="padding:6px 10px;border-bottom:1px solid #e5e5e5;text-align:right"';
const tdl = 'style="padding:6px 10px;border-bottom:1px solid #e5e5e5;text-align:left"';
const th = 'style="padding:6px 10px;background:#f3f4f6;text-align:right;font-weight:600"';
const thl = 'style="padding:6px 10px;background:#f3f4f6;text-align:left;font-weight:600"';
const T = filas.reduce((t, f) => { for (const k of ['total', 'anterior', 'ventas', 'cotizacion', 'perdidos', 'sinIA', 'conversando']) t[k] = (t[k] || 0) + f[k]; return t; }, {});
let html = `<div style="font-family:Arial,sans-serif;color:#222;max-width:760px">
<h2 style="margin:0 0 4px">Reporte semanal – Rs Viajes</h2>
<p style="margin:0 0 16px;color:#555">Leads que llegaron del ${fmt(ahora - 7 * DIA)} al ${fmt(ahora)}, y en qué etapa están hoy.</p>
<table style="border-collapse:collapse;width:100%;font-size:14px">
<tr><th ${thl}>Agencia</th><th ${th}>Leads</th><th ${th}>vs. semana ant.</th><th ${th}>Datos completos / cotización</th><th ${th}>Ventas</th><th ${th}>Perdidos</th><th ${th}>Sin IA</th><th ${th}>Aún conversando</th></tr>`;
for (const f of filas) {
  const av = f.cotizacion + f.ventas;
  html += `<tr><td ${tdl}><b>${f.nombre}</b></td><td ${td}>${f.total}</td><td ${td}>${f.anterior} ${flecha(f.total, f.anterior)}</td><td ${td}>${av} (${pct(av, f.total)})</td><td ${td}>${f.ventas}</td><td ${td}>${f.perdidos}</td><td ${td}>${f.sinIA}</td><td ${td}>${f.conversando}</td></tr>`;
}
const avT = T.cotizacion + T.ventas;
html += `<tr><td ${tdl}><b>Total</b></td><td ${td}><b>${T.total}</b></td><td ${td}>${T.anterior} ${flecha(T.total, T.anterior)}</td><td ${td}><b>${avT} (${pct(avT, T.total)})</b></td><td ${td}><b>${T.ventas}</b></td><td ${td}>${T.perdidos}</td><td ${td}>${T.sinIA}</td><td ${td}>${T.conversando}</td></tr></table>
<p style="font-size:12px;color:#666;margin:6px 0 20px">Perdidos = Última oportunidad + Cliente perdido. Sin IA = WhatsApp que no viene de anuncio (lo atiende una persona). Ventas = Con anticipo, Pagado, Mañana sale, En destino, De regreso o Cliente ganado.</p>
<h3 style="margin:0 0 6px">Pruebas diarias del sistema</h3><table style="border-collapse:collapse;font-size:14px">`;
for (const f of filas) {
  const p = pr[f.ag];
  const txt = !p ? 'sin pruebas registradas' : p.ok === p.total ? `✅ ${p.ok} de ${p.total} bien` : `⚠️ ${p.ok} de ${p.total} bien<br><span style="font-size:12px;color:#cf222e">${p.fallos.slice(0, 3).join('<br>')}</span>`;
  html += `<tr><td ${tdl}><b>${f.nombre}</b></td><td ${tdl}>${txt}</td></tr>`;
}
html += `</table><h3 style="margin:20px 0 6px">Detalle por etapa</h3>`;
for (const f of filas) {
  if (!f.total) { html += `<p style="margin:4px 0"><b>${f.nombre}:</b> sin leads esta semana.</p>`; continue; }
  html += `<p style="margin:4px 0"><b>${f.nombre}:</b> ${f.etapas.map(([n, c]) => `${n} ${c}`).join(' · ')}</p>`;
}
html += `</div>`;
const caidas = filas.filter(f => f.anterior && f.total < f.anterior * 0.7).map(f => f.nombre);
const asunto = `Reporte semanal Rs Viajes: ${T.total} leads, ${pct(avT, T.total)} a cotización` + (caidas.length ? ` · baja en ${caidas.join(', ')}` : '');
return [{ json: { asunto, html } }];
